update sc_plans set spec=jsonb_set(spec,'{shots}',coalesce(spec->'shots','[]'::jsonb) || $q$[{"n": 3, "id": "gh3_call", "vid": "ghv3_call", "img_prompt": "PLACE: a hanok courtyard with a wooden porch (maru), a jangdokdae of round brown earthenware crocks on a stone platform, a wooden gate with a small tiled roof, a persimmon tree. Snowy winter afternoon. Kachi lands on the small tiled roof of the wooden gate and calls out with its beak open toward the courtyard; snow falls; far below in soft focus, the grandma beside the crocks turns toward the gate. The magpie is exactly the character in the magpie reference image: a small round chibi magpie with a glossy black head, cream-white face and belly, big shiny dark-brown eyes, short black beak, dark navy-blue wings, a red knotted neckerchief and a small brown leather satchel. It does NOT hold a microphone. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/c1_magpie.jpeg", "social/side/gen/gh2_wait.jpeg"], "reuse": null, "action": "Kachi opens its beak in a cheerful call and flutters its wings once; snow falls softly.", "dur": 5, "cap": "In Korea, a magpie's call means someone is coming.", "detail": "까치 울음 = 반가운 손님(한국 속설)"}, {"n": 4, "id": "gh4_turn", "vid": "ghv4_turn", "img_prompt": "GRANDMA (now): the same Korean grandma, now in her eighties, snow-white hair in a low bun, deeper smile wrinkles, the same indigo quilted vest, a little more bent. WOMAN (now): the same granddaughter grown into a young woman in her late twenties, round face, black bob with bangs, a bright red wool coat. a small brass spoon with a tiny heart engraved on the handle Snowy winter on the wooden porch. The granddaughter, now grown, sits beside her grandma and gently feeds her a spoonful of the red persimmon with the same small brass spoon with the heart on the handle; the grandma's eyes are wet and she smiles like a child. Snow falls in the courtyard behind them. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/gh1_spoon.jpeg", "social/side/gen/gh2_wait.jpeg"], "reuse": null, "action": "The grandma slowly takes the spoonful and smiles through happy tears; the young woman smiles warmly.", "dur": 5, "cap": "This time, I fed her.", "detail": "같은 숟가락 — 이번엔 손녀가 먹여 준다(역할 반전)"}]$q$::jsonb) where id='P261031-grandma-hongsi'